{"content": "     1|/**
     2| * MCTS (Monte Carlo Tree Search) for Go.
     3| * Lightweight implementation — no neural network, pure simulation.
     4| */
     5|import { BOARD_SIZE, applyMove, countLiberties, getGroup } from './index.js'
     6|
     7|const DIRS = [[-1,0],[1,0],[0,-1],[0,1]]
     8|const SIM_LIMITS = { easy: 50, medium: 200, hard: 800, expert: 3000 }
     9|
    10|class MCTSNode {
    11|  constructor(board, player, parent = null, move = null) {
    12|    this.board = board
    13|    this.player = player  // player whose turn it is
    14|    this.parent = parent
    15|    this.move = move      // { r, c } that led here
    16|    this.children = []
    17|    this.wins = 0
    18|    this.visits = 0
    19|    this.untriedMoves = null
    20|  }
    21|
    22|  ucb1(exploration = 1.41) {
    23|    if (this.visits === 0) return Infinity
    24|    return this.wins / this.visits + exploration * Math.sqrt(Math.log(this.parent.visits) / this.visits)
    25|  }
    26|
    27|  bestChild() {
    28|    let best = null, bestScore = -Infinity
    29|    for (const child of this.children) {
    30|      const score = child.ucb1()
    31|      if (score > bestScore) { bestScore = score; best = child }
    32|    }
    33|    return best
    34|  }
    35|}
    36|
    37|/** Get candidate moves near existing stones (within 2 cells). */
    38|function getCandidateMoves(board) {
    39|  const candidates = new Set()
    40|  const range = 2
    41|  for (let r = 0; r < BOARD_SIZE; r++) {
    42|    for (let c = 0; c < BOARD_SIZE; c++) {
    43|      if (board[r][c] !== 0) {
    44|        for (let dr = -range; dr <= range; dr++) {
    45|          for (let dc = -range; dc <= range; dc++) {
    46|            const nr = r + dr, nc = c + dc
    47|            if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE && board[nr][nc] === 0) {
    48|              candidates.add(`${nr},${nc}`)
    49|            }
    50|          }
    51|        }
    52|      }
    53|    }
    54|  }
    55|  // Empty board → play center
    56|  if (candidates.size === 0) candidates.add(`${Math.floor(BOARD_SIZE/2)},${Math.floor(BOARD_SIZE/2)}`)
    57|  return [...candidates].map(s => { const [r, c] = s.split(',').map(Number); return { r, c } })
    58|}
    59|
    60|/** Expand node by adding one child. */
    61|function expand(node) {
    62|  if (!node.untriedMoves) node.untriedMoves = getCandidateMoves(node.board)
    63|  if (node.untriedMoves.length === 0) return null
    64|
    65|  const idx = Math.floor(Math.random() * node.untriedMoves.length)
    66|  const move = node.untriedMoves.splice(idx, 1)[0]
    67|  const result = applyMove(node.board, move.r, move.c, node.player)
    68|  if (!result) return null  // illegal move
    69|
    70|  const child = new MCTSNode(result.board, 3 - node.player, node, move)
    71|  node.children.push(child)
    72|  return child
    73|}
    74|
    75|/** Random playout from a board state. Returns winner (1 or 2). */
    76|function simulate(board, player) {
    77|  const simBoard = board.map(row => [...row])
    78|  let cur = player
    79|  let consecutivePasses = 0
    80|  const maxMoves = 200  // cap playout length
    81|
    82|  for (let i = 0; i < maxMoves; i++) {
    83|    // Get random empty cell near existing stones
    84|    const candidates = []
    85|    for (let r = 0; r < BOARD_SIZE; r++)
    86|      for (let c = 0; c < BOARD_SIZE; c++)
    87|        if (simBoard[r][c] === 0) {
    88|          // Check if adjacent to any stone
    89|          let near = false
    90|          for (const [dr, dc] of DIRS) {
    91|            const nr = r+dr, nc = c+dc
    92|            if (nr >= 0 && nr < BOARD_SIZE && nc >= 0 && nc < BOARD_SIZE && simBoard[nr][nc] !== 0) {
    93|              near = true; break
    94|            }
    95|          }
    96|          if (near) candidates.push({ r, c })
    97|        }
    98|
    99|    if (candidates.length === 0) {
   100|      consecutivePasses++
   101|      if (consecutivePasses >= 2) break
   102|      cur = 3 - cur
   103|      continue
   104|    }
   105|    consecutivePasses = 0
   106|
   107|    // Pick random candidate
   108|    const move = candidates[Math.floor(Math.random() * candidates.length)]
   109|    const result = applyMove(simBoard, move.r, move.c, cur)
   110|    if (!result) { cur = 3 - cur; continue }
   111|    for (let r = 0; r < BOARD_SIZE; r++) simBoard[r] = result.board[r]
   112|    cur = 3 - cur
   113|  }
   114|
   115|  // Score-based winner
   116|  let black = 0, white = 0
   117|  for (let r = 0; r < BOARD_SIZE; r++)
   118|    for (let c = 0; c < BOARD_SIZE; c++) {
   119|      if (simBoard[r][c] === 1) black++
   120|      else if (simBoard[r][c] === 2) white++
   121|    }
   122|  return white + 6.5 > black ? 2 : 1
   123|}
   124|
   125|/** Backpropagate result up the tree. */
   126|function backpropagate(node, winner) {
   127|  let current = node
   128|  while (current) {
   129|    current.visits++
   130|    if (winner === current.player) current.wins++  // wins for the player who moved to get here
   131|    current = current.parent
   132|  }
   133|}
   134|
   135|/**
   136| * Get best move via MCTS.
   137| * @param {number[][]} board - 19×19 board (0=empty, 1=black, 2=white)
   138| * @param {number} player - current player (1 or 2)
   139| * @param {string} difficulty - 'easy'|'medium'|'hard'|'expert'
   140| * @returns {{ r: number, c: number }}
   141| */
   142|export function getBestMove(board, player, difficulty = 'medium') {
   143|  const limit = SIM_LIMITS[difficulty] || 500
   144|  const root = new MCTSNode(board.map(row => [...row]), player)
   145|
   146|  for (let i = 0; i < limit; i++) {
   147|    // Select
   148|    let node = root
   149|    while (node.children.length > 0 && (!node.untriedMoves || node.untriedMoves.length === 0)) {
   150|      node = node.bestChild()
   151|    }
   152|    // Expand
   153|    const child = expand(node)
   154|    if (child) node = child
   155|    // Simulate
   156|    const winner = simulate(node.board, node.player)
   157|    // Backpropagate
   158|    backpropagate(node, winner)
   159|  }
   160|
   161|  // Pick most visited child
   162|  let best = null, bestVisits = 0
   163|  for (const child of root.children) {
   164|    if (child.visits > bestVisits) { bestVisits = child.visits; best = child }
   165|  }
   166|  return best?.move ?? getCandidateMoves(board)[0]
   167|}
