export const GO_BOARD_SIZE = 19
export const GO_CELL = 28
export const GO_PADDING = 20

export function goBoardPixelSize() {
  const s = GO_PADDING * 2 + GO_CELL * (GO_BOARD_SIZE - 1)
  return { w: s, h: s }
}

// Star points for 19x19 board (row, col)
const STAR_POINTS = [
  [3, 3], [3, 9], [3, 15],
  [9, 3], [9, 9], [9, 15],
  [15, 3], [15, 9], [15, 15],
]

const COL_LABELS = 'ABCDEFGHJKLMNOPQRST'

function drawBoardCore(ctx, dpr, { board, lastMove, isThinking }) {
  const CELL = GO_CELL * dpr
  const PAD = GO_PADDING * dpr
  const size = PAD * 2 + CELL * (GO_BOARD_SIZE - 1)

  ctx.save()
  ctx.scale(dpr, dpr)

  const rootStyle = getComputedStyle(document.documentElement)
  const boardColor = rootStyle.getPropertyValue('--bg-surface').trim() || '#dcb35c'
  const lineColor = '#1a1a1a'
  const accentColor = rootStyle.getPropertyValue('--accent-primary').trim() || '#00d4ff'
  const blackStoneColor = '#1a1a1a'
  const whiteStoneColor = '#f0f0f0'

  // Board background
  ctx.fillStyle = boardColor
  ctx.fillRect(0, 0, size, size)

  // Grid lines
  ctx.strokeStyle = lineColor
  ctx.lineWidth = 1
  for (let i = 0; i < GO_BOARD_SIZE; i++) {
    const pos = PAD + i * CELL
    // Horizontal
    ctx.beginPath()
    ctx.moveTo(PAD, pos)
    ctx.lineTo(PAD + (GO_BOARD_SIZE - 1) * CELL, pos)
    ctx.stroke()
    // Vertical
    ctx.beginPath()
    ctx.moveTo(pos, PAD)
    ctx.lineTo(pos, PAD + (GO_BOARD_SIZE - 1) * CELL)
    ctx.stroke()
  }

  // Star points
  ctx.fillStyle = lineColor
  for (const [r, c] of STAR_POINTS) {
    const cx = PAD + c * CELL
    const cy = PAD + r * CELL
    ctx.beginPath()
    ctx.arc(cx, cy, CELL * 0.12, 0, Math.PI * 2)
    ctx.fill()
  }

  // Coordinate labels
  ctx.fillStyle = 'rgba(0, 0, 0, 0.45)'
  ctx.font = `${Math.round(CELL * 0.32)}px monospace`
  ctx.textAlign = 'center'
  ctx.textBaseline = 'top'
  for (let c = 0; c < GO_BOARD_SIZE; c++) {
    ctx.fillText(COL_LABELS[c], PAD + c * CELL, PAD + GO_BOARD_SIZE * CELL + 2)
  }
  ctx.textBaseline = 'bottom'
  for (let r = 0; r < GO_BOARD_SIZE; r++) {
    ctx.fillText(String(GO_BOARD_SIZE - r), PAD - GO_BOARD_SIZE * CELL - 8, PAD + r * CELL + 2)
  }

  // Last move highlight (small triangle marker)
  if (lastMove) {
    const lx = PAD + lastMove.c * CELL
    const ly = PAD + lastMove.r * CELL
    const markerR = CELL * 0.18
    ctx.fillStyle = board[lastMove.r][lastMove.c] === 1 ? '#ff5555' : '#ff5555'
    ctx.beginPath()
    ctx.arc(lx, ly, markerR, 0, Math.PI * 2)
    ctx.fill()
  }

  // Stones
  const stoneR = CELL * 0.44
  for (let r = 0; r < GO_BOARD_SIZE; r++) {
    for (let c = 0; c < GO_BOARD_SIZE; c++) {
      const p = board[r][c]
      if (p === 0) continue
      const cx = PAD + c * CELL
      const cy = PAD + r * CELL

      // Shadow
      ctx.beginPath()
      ctx.arc(cx + 1.5, cy + 1.5, stoneR, 0, Math.PI * 2)
      ctx.fillStyle = 'rgba(0,0,0,0.25)'
      ctx.fill()

      // Stone body
      ctx.beginPath()
      ctx.arc(cx, cy, stoneR, 0, Math.PI * 2)
      if (p === 1) {
        // Black stone with gradient
        const grad = ctx.createRadialGradient(cx - stoneR * 0.3, cy - stoneR * 0.3, stoneR * 0.1, cx, cy, stoneR)
        grad.addColorStop(0, '#555')
        grad.addColorStop(1, blackStoneColor)
        ctx.fillStyle = grad
      } else {
        // White stone with gradient
        const grad = ctx.createRadialGradient(cx - stoneR * 0.3, cy - stoneR * 0.3, stoneR * 0.1, cx, cy, stoneR)
        grad.addColorStop(0, '#fff')
        grad.addColorStop(1, whiteStoneColor)
        ctx.fillStyle = grad
      }
      ctx.fill()

      // Stone edge
      ctx.strokeStyle = p === 1 ? 'rgba(0,0,0,0.5)' : 'rgba(0,0,0,0.15)'
      ctx.lineWidth = 0.8
      ctx.stroke()
    }
  }

  // Last move marker on top of stone
  if (lastMove && board[lastMove.r][lastMove.c] !== 0) {
    const lx = PAD + lastMove.c * CELL
    const ly = PAD + lastMove.r * CELL
    const markerR = CELL * 0.15
    ctx.beginPath()
    ctx.arc(lx, ly, markerR, 0, Math.PI * 2)
    ctx.fillStyle = board[lastMove.r][lastMove.c] === 1 ? '#ff6666' : '#cc3333'
    ctx.fill()
  }

  // Thinking overlay
  if (isThinking) {
    ctx.fillStyle = 'rgba(0,0,0,0.08)'
    ctx.fillRect(0, 0, size, size)
  }

  ctx.restore()
}

function eventToRc(e, canvas, dpr) {
  const rect = canvas.getBoundingClientRect()
  const CELL = GO_CELL * dpr
  const PAD = GO_PADDING * dpr
  const mx = ((e.clientX ?? e.touches?.[0]?.clientX) - rect.left) * (canvas.width / rect.width)
  const my = ((e.clientY ?? e.touches?.[0]?.clientY) - rect.top) * (canvas.height / rect.height)
  const c = Math.round((mx - PAD) / CELL)
  const r = Math.round((my - PAD) / CELL)
  if (r < 0 || r >= GO_BOARD_SIZE || c < 0 || c >= GO_BOARD_SIZE) return null
  return { r, c }
}

export default function GoBoard({
  board,
  lastMove,
  onPlaceStone,
  gameOver,
  isThinking,
  interactionLocked = false,
}) {
  const canvasRef = useRef(null)
  const dprRef = useRef(typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1)

  const { w, h } = goBoardPixelSize()

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const dpr = dprRef.current
    canvas.width = w * dpr
    canvas.height = h * dpr
    const ctx = canvas.getContext('2d')
    drawBoardCore(ctx, dpr, { board, lastMove, isThinking })
  }, [board, lastMove, isThinking, w, h])

  const canInteract = useCallback(() => {
    if (interactionLocked || gameOver || isThinking) return false
    return true
  }, [interactionLocked, gameOver, isThinking])

  const handleClick = useCallback(
    (e) => {
      if (!canInteract()) return
      const rc = eventToRc(e, canvasRef.current, dprRef.current)
      if (rc) onPlaceStone(rc.r, rc.c)
    },
    [canInteract, onPlaceStone],
  )

  return (
    <canvas
      ref={canvasRef}
      width={w}
      height={h}
      onClick={handleClick}
      onTouchEnd={(e) => {
        e.preventDefault()
        handleClick(e)
      }}
      style={{
        width: '100%',
        maxWidth: 'min(96vw, 560px)',
        height: 'auto',
        aspectRatio: `${w} / ${h}`,
        touchAction: 'manipulation',
        cursor: canInteract() ? 'pointer' : 'default',
        opacity: isThinking ? 0.88 : 1,
        borderRadius: 2,
        boxShadow: '0 8px 32px rgba(0,0,0,0.25)',
      }}
    />
  )
}
"}

{"path": "/Users/charles/Desktop/folder/gomoku-react/apps/web/src/components/go/GoBoardArea.jsx", "content": "import GoBoard from './GoBoard.jsx'
import AIThinkingIndicator from '../board/AIThinkingIndicator.jsx'

export default function GoBoardArea({
  board,
  currentPlayer,
  moveHistory,
  gameOver,
  winnerSide,
  endReason,
  blackCaptures,
  whiteCaptures,
  lastMove,
  onPlaceStone,
  aiMode,
  isThinking,
  score,
  interactionLocked = false,
}) {
  const moveNum = moveHistory.length

  let statusMain = '对局中'
  if (gameOver) {
    if (endReason === 'resign' && winnerSide != null) {
      statusMain = winnerSide === 1 ? '黑方胜 · 认输' : '白方胜 · 认输'
    } else if (endReason === 'pass') {
      statusMain = winnerSide === 1 ? '黑方胜' : winnerSide === 2 ? '白方胜' : '终局'
    } else if (endReason === 'two_pass') {
      if (score) {
        statusMain = score.black > score.white ? '黑方胜' : score.white > score.black ? '白方胜' : '和棋'
      } else {
        statusMain = '终局'
      }
    } else {
      statusMain = '终局'
    }
  } else {
    statusMain = currentPlayer === 1 ? '黑方落子' : '白方落子'
  }

  const statusSub = gameOver
    ? `GO · ${moveNum} MOVES${score ? ` · B ${Math.round(score.black)} - W ${Math.round(score.white)}` : ''}`
    : `第 ${moveNum + 1} 手 · ${aiMode && isThinking ? 'AI 思考中' : 'READY'}${blackCaptures + whiteCaptures > 0 ? ` · 提子 B${blackCaptures} W${whiteCaptures}` : ''}`

  return (
    <main className="flex items-center justify-center p-2 md:p-6">
      <div className="flex flex-col items-center gap-4 w-full max-w-[600px]">
        <div className="text-center min-h-[52px] flex flex-col items-center justify-center">
          <div className="font-calligraphy text-xl md:text-[22px] text-ink tracking-[3px] transition-all">
            {statusMain}
          </div>
          <div className="font-mono text-[10px] text-ink-faint tracking-[0.15em] mt-0.5 uppercase">
            {statusSub}
          </div>
        </div>

        <div className="relative w-full flex justify-center">
          <GoBoard
            board={board}
            lastMove={lastMove}
            onPlaceStone={onPlaceStone}
            gameOver={gameOver}
            isThinking={isThinking}
            interactionLocked={interactionLocked}
          />
          <AIThinkingIndicator show={Boolean(aiMode && isThinking)} />

          {/* Game over overlay */}
          {gameOver && (
            <div style={{
              position: 'absolute',
              inset: 0,
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              background: 'color-mix(in srgb, var(--bg-primary) 88%, transparent)',
              backdropFilter: 'blur(4px)',
              zIndex: 10,
              borderRadius: 2,
              animation: 'fadeIn 0.4s ease',
            }}>
              <div style={{
                fontSize: 36,
                fontWeight: 'bold',
                fontFamily: 'var(--font-display, "Kaiti SC", serif)',
                letterSpacing: '0.25em',
                color: 'var(--text-primary)',
                marginBottom: 8,
                textShadow: '0 0 24px color-mix(in srgb, var(--accent-primary) 40%, transparent)',
              }}>
                {endReason === 'two_pass'
                  ? (score ? (score.black > score.white ? '黑方胜' : score.white > score.black ? '白方胜' : '和棋') : '终局')
                  : endReason === 'resign'
                    ? (winnerSide === 1 ? '黑方胜' : '白方胜')
                    : '终局'}
              </div>
              <div style={{
                fontSize: 11,
                color: 'var(--text-muted)',
                fontFamily: 'var(--font-primary)',
                letterSpacing: '0.2em',
                marginBottom: 4,
              }}>
                {endReason === 'resign' ? 'RESIGN' : endReason === 'two_pass' ? 'TWO PASSES' : endReason === 'pass' ? 'PASS' : 'GAME OVER'}
              </div>
              {score && (
                <div style={{
                  fontSize: 12,
                  color: 'var(--text-muted)',
                  fontFamily: 'monospace',
                  letterSpacing: '0.1em',
                }}>
                  B {Math.round(score.black)} - W {Math.round(score.white)}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </main>
  )
}
"}

