import { goGame } from '@tg/core'

const { BOARD_SIZE, createBoard, applyMove, estimateScore } = goGame

export function useGoGame() {
  const [board, setBoard] = useState(() => createBoard())
  const [currentPlayer, setCurrentPlayer] = useState(1) // 1=black, 2=white
  const [moveHistory, setMoveHistory] = useState([])
  const [gameOver, setGameOver] = useState(false)
  const [endReason, setEndReason] = useState(null)
  const [winnerSide, setWinnerSide] = useState(null)
  const [lastMove, setLastMove] = useState(null)
  const [blackCaptures, setBlackCaptures] = useState(0)
  const [whiteCaptures, setWhiteCaptures] = useState(0)
  const [score, setScore] = useState(null)
  const [consecutivePasses, setConsecutivePasses] = useState(0)

  const boardRef = useRef(board)
  const playerRef = useRef(currentPlayer)
  const gameOverRef = useRef(gameOver)
  boardRef.current = board
  playerRef.current = currentPlayer
  gameOverRef.current = gameOver

  const placeStone = useCallback((r, c) => {
    if (gameOverRef.current) return false
    const b = boardRef.current
    const p = playerRef.current

    const result = applyMove(b, r, c, p)
    if (!result) return false

    setBoard(result.board)
    boardRef.current = result.board

    // Update captures
    if (p === 1) {
      setBlackCaptures((v) => v + result.captured)
    } else {
      setWhiteCaptures((v) => v + result.captured)
    }

    setMoveHistory((h) => [...h, { r, c, player: p, captured: result.captured }])
    setLastMove({ r, c })
    setConsecutivePasses(0)

    const next = p === 1 ? 2 : 1
    setCurrentPlayer(next)
    playerRef.current = next

    return true
  }, [])

  const pass = useCallback(() => {
    if (gameOverRef.current) return
    const p = playerRef.current
    setMoveHistory((h) => [...h, { r: -1, c: -1, player: p, captured: 0, pass: true }])
    setLastMove(null)

    const newPasses = consecutivePasses + 1
    setConsecutivePasses(newPasses)

    if (newPasses >= 2) {
      // Two consecutive passes → game over, score
      const s = estimateScore(boardRef.current)
      setScore(s)
      setGameOver(true)
      gameOverRef.current = true
      setEndReason('two_pass')
      setWinnerSide(s.black > s.white ? 1 : s.white > s.black ? 2 : null)
      return
    }

    const next = p === 1 ? 2 : 1
    setCurrentPlayer(next)
    playerRef.current = next
  }, [consecutivePasses])

  const resign = useCallback(() => {
    if (gameOverRef.current) return
    const loser = playerRef.current
    const s = estimateScore(boardRef.current)
    setScore(s)
    setGameOver(true)
    gameOverRef.current = true
    setEndReason('resign')
    setWinnerSide(loser === 1 ? 2 : 1)
  }, [])

  const newGame = useCallback(() => {
    const fresh = createBoard()
    setBoard(fresh)
    boardRef.current = fresh
    setCurrentPlayer(1)
    playerRef.current = 1
    setMoveHistory([])
    setGameOver(false)
    gameOverRef.current = false
    setEndReason(null)
    setWinnerSide(null)
    setLastMove(null)
    setBlackCaptures(0)
    setWhiteCaptures(0)
    setScore(null)
    setConsecutivePasses(0)
  }, [])

  const undoMove = useCallback((popTwo = false) => {
    setMoveHistory((hist) => {
      if (hist.length === 0) return hist
      let h2 = hist.slice(0, -1)
      if (popTwo && h2.length > 0) h2 = h2.slice(0, -1)

      // Rebuild board from history
      const fresh = createBoard()
      let bc = 0, wc = 0
      for (const m of h2) {
        if (m.pass) continue
        const result = applyMove(fresh, m.r, m.c, m.player)
        if (result) {
          for (let r = 0; r < BOARD_SIZE; r++) fresh[r] = result.board[r]
          if (m.player === 1) bc += result.captured
          else wc += result.captured
        }
      }

      setBoard(fresh.map((row) => [...row]))
      boardRef.current = fresh
      setBlackCaptures(bc)
      setWhiteCaptures(wc)
      setCurrentPlayer(h2.length % 2 === 0 ? 1 : 2)
      playerRef.current = h2.length % 2 === 0 ? 1 : 2
      setGameOver(false)
      gameOverRef.current = false
      setEndReason(null)
      setWinnerSide(null)
      setScore(null)

      // Recount consecutive passes
      let cp = 0
      for (let i = h2.length - 1; i >= 0; i--) {
        if (h2[i].pass) cp++
        else break
      }
      setConsecutivePasses(cp)

      const last = h2.length > 0 ? h2[h2.length - 1] : null
      setLastMove(last && !last.pass ? { r: last.r, c: last.c } : null)

      return h2
    })
  }, [])

  const exportRecord = useCallback(() => {
    const payload = {
      game: 'go',
      version: 1,
      boardSize: BOARD_SIZE,
      moves: moveHistory,
      blackCaptures,
      whiteCaptures,
    }
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' })
    const a = document.createElement('a')
    a.href = URL.createObjectURL(blob)
    a.download = `go-${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(a.href)
  }, [moveHistory, blackCaptures, whiteCaptures])

  useEffect(() => {
    gameOverRef.current = gameOver
  }, [gameOver])

  return {
    board,
    BOARD_SIZE,
    currentPlayer,
    moveHistory,
    gameOver,
    endReason,
    winnerSide,
    lastMove,
    blackCaptures,
    whiteCaptures,
    score,
    placeStone,
    pass,
    resign,
    newGame,
    undoMove,
    exportRecord,
  }
}
"}

{"content": "import { useState, useCallback, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import Header from '../components/Header.jsx'
import Footer from '../components/Footer.jsx'
import ModeSelect from '../components/ModeSelect.jsx'
import PlayerCard from '../components/player/PlayerCard.jsx'
import ControlButtons from '../components/controls/ControlButtons.jsx'
import GoBoardArea from '../components/go/GoBoardArea.jsx'
import { useGoGame } from '../hooks/useGoGame.js'
import { useTimer } from '../hooks/useTimer.js'
import { useAI } from '../hooks/useAI.js'

export default function GoPlayPage() {
  const navigate = useNavigate()
  const { gameId: selectedGame = 'go' } = useParams()
  const [currentView, setCurrentView] = useState('mode')
  const [aiMode, setAiMode] = useState(false)
  const [difficulty, setDifficulty] = useState('medium')

  const g = useGoGame()

  const timerPlayer = g.currentPlayer === 1 ? 1 : 2
  const { timers, startTimer, resetTimers } = useTimer(timerPlayer, g.gameOver)

  useEffect(() => {
    if (g.moveHistory.length === 1) startTimer()
  }, [g.moveHistory.length, startTimer])

  const { placeStone } = g
  const onAIMove = useCallback(
    (r, c) => {
      placeStone(r, c)
    },
    [placeStone],
  )

  const { isThinking } = useAI({
    board: g.board,
    currentPlayer: g.currentPlayer,
    aiMode,
    difficulty,
    gameOver: g.gameOver,
    gameKind: 'go',
    aiSide: 2, // AI plays white
    onAIMove,
  })

  const interactionLocked = Boolean((aiMode && g.currentPlayer === 2) || isThinking)

  const handleNewGame = useCallback(() => {
    g.newGame()
    resetTimers()
  }, [g, resetTimers])

  const handleUndo = useCallback(() => {
    if (g.gameOver) return
    g.undoMove(aiMode)
  }, [g, aiMode])

  const handleToggleAI = useCallback(() => {
    setAiMode((v) => !v)
    g.newGame()
    resetTimers()
  }, [g, resetTimers])

  const handleResign = useCallback(() => {
    if (g.gameOver || g.moveHistory.length === 0) return
    g.resign()
  }, [g])

  const handlePass = useCallback(() => {
    if (g.gameOver) return
    g.pass()
  }, [g])

  if (currentView === 'mode') {
    return (
      <ModeSelect
        gameId={selectedGame}
        webrtc={null}
        sig={null}
        networkModesEnabled={false}
        onSelectMode={(mode, opts) => {
          if (mode === 'ai') {
            setAiMode(true)
            if (opts?.difficulty) setDifficulty(opts.difficulty)
          } else {
            setAiMode(false)
          }
          g.newGame()
          resetTimers()
          setCurrentView('game')
        }}
        onBack={() => navigate('/')}
        autoJoinOffer={null}
        autoJoinRoomCode={null}
      />
    )
  }

  return (
    <div
      className="flex flex-col"
      style={{ minHeight: '100svh', backgroundColor: 'var(--bg-primary)', color: 'var(--text-primary)' }}
    >
      <Header
        moveCount={g.moveHistory.length}
        gameId={`go-${g.moveHistory.length}`}
        onBackToLobby={() => navigate('/')}
      />

      <div
        className="md:hidden flex gap-2 px-3 py-2 flex-shrink-0"
        style={{
          borderBottom: '1px solid var(--border-color)',
          paddingLeft: 'max(12px, env(safe-area-inset-left))',
          paddingRight: 'max(12px, env(safe-area-inset-right))',
        }}
      >
        <div className="flex-1">
          <PlayerCard
            player={1}
            name="黑方"
            type={aiMode ? '本机 · 执黑' : '本地'}
            timer={timers.black}
            isActive={g.currentPlayer === 1 && !g.gameOver}
          />
        </div>
        <div className="flex-1">
          <PlayerCard
            player={2}
            name={aiMode ? 'AI' : '白方'}
            type={aiMode ? `AI · ${difficulty.toUpperCase()}` : '本地'}
            timer={timers.white}
            isActive={g.currentPlayer === 2 && !g.gameOver}
          />
        </div>
      </div>

      <div className="flex flex-1" style={{ minHeight: 0 }}>
        <aside className="hidden md:flex md:flex-col w-56 flex-shrink-0 overflow-y-auto" style={{ borderRight: '1px solid var(--border-color)' }}>
          <div className="p-5 flex flex-col gap-5">
            <div className="flex flex-col gap-2">
              <PlayerCard
                player={1}
                name="黑方"
                type={aiMode ? 'PLAYER · 执黑' : 'PLAYER · 本地'}
                timer={timers.black}
                isActive={g.currentPlayer === 1 && !g.gameOver}
              />
              <PlayerCard
                player={2}
                name={aiMode ? 'AI' : '白方'}
                type={aiMode ? `AI · ${difficulty.toUpperCase()}` : 'PLAYER · 本地'}
                timer={timers.white}
                isActive={g.currentPlayer === 2 && !g.gameOver}
              />
            </div>
            <ControlButtons
              onNewGame={handleNewGame}
              onUndo={handleUndo}
              onToggleAI={handleToggleAI}
              onExport={g.exportRecord}
              onResign={handleResign}
              onPass={handlePass}
              aiMode={aiMode}
              gameOver={g.gameOver}
              canUndo={g.moveHistory.length > 0}
              mode="all"
            />
            <p className="text-[9px] leading-relaxed" style={{ color: 'var(--text-muted)' }}>
              围棋对局为本地 + 人机。支持提子规则，双方连续跳过终局计分（中国规则，贴目 6.5）。
            </p>
          </div>
        </aside>

        <div className="flex-1 overflow-auto flex flex-col relative">
          <GoBoardArea
            board={g.board}
            currentPlayer={g.currentPlayer}
            moveHistory={g.moveHistory}
            gameOver={g.gameOver}
            endReason={g.endReason}
            winnerSide={g.winnerSide}
            blackCaptures={g.blackCaptures}
            whiteCaptures={g.whiteCaptures}
            lastMove={g.lastMove}
            onPlaceStone={g.placeStone}
            aiMode={aiMode}
            isThinking={isThinking}
            score={g.score}
            interactionLocked={interactionLocked}
          />
          <div className="md:hidden px-2 pb-2 flex flex-col gap-2">
            <ControlButtons
              onNewGame={handleNewGame}
              onUndo={handleUndo}
              onToggleAI={handleToggleAI}
              onExport={g.exportRecord}
              onResign={handleResign}
              onPass={handlePass}
              aiMode={aiMode}
              gameOver={g.gameOver}
              canUndo={g.moveHistory.length > 0}
              mode="primary"
            />
          </div>
        </div>
      </div>

      {g.gameOver && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center px-4"
          style={{ background: 'color-mix(in srgb, var(--bg-primary) 86%, transparent)' }}
          role="dialog"
          aria-modal="true"
        >
          <div
            className="max-w-sm w-full p-6 rounded-lg border text-center"
            style={{
              background: 'var(--bg-surface)',
              borderColor: 'var(--border-color)',
            }}
          >
            <div className="font-calligraphy text-2xl tracking-widest mb-3">
              {g.endReason === 'two_pass'
                ? (g.score ? (g.score.black > g.score.white ? '黑方胜' : g.score.white > g.score.black ? '白方胜' : '和棋') : '终局')
                : g.endReason === 'resign'
                  ? (g.winnerSide === 1 ? '黑方胜' : '白方胜')
                  : '终局'}
            </div>
            <div className="text-xs mb-2" style={{ color: 'var(--text-muted)' }}>
              {g.endReason === 'resign' ? '认输结束' : g.endReason === 'two_pass' ? '双方跳过，计分终局' : ''}
            </div>
            {g.score && (
              <div className="text-xs mb-4 font-mono" style={{ color: 'var(--text-muted)' }}>
                黑 {Math.round(g.score.black)} - 白 {Math.round(g.score.white)}
              </div>
            )}
            <button
              type="button"
              onClick={handleNewGame}
              className="w-full py-3 font-serif-sc text-sm tracking-[0.2em]"
              style={{ background: 'var(--text-primary)', color: 'var(--bg-primary)' }}
            >
              再来一局
            </button>
          </div>
        </div>
      )}

      <Footer gameId="go" networkMode="offline-solo" isEncrypted={false} />
    </div>
  )
}
